// by reading positional arguments from cli.input.

const cli = meow(
  `
  Usage
    $ greet <command>

  Commands
    hello    Say hello to someone
    goodbye  Say goodbye to someone

  Options
    --name        Name to greet (default: World)
    --uppercase   Print greeting in uppercase
    --formal      Use formal farewell
`,
